/**
 * SUMO IS A BOXER — Asset Authoring Kit
 *
 * Every asset in this game is CODE. Nothing is downloaded, imported from a DCC
 * tool, or generated by an image/mesh service. This module is the game-owned
 * layer that sits directly on top of the engine's public modeling verbs.
 *
 * ENGINE VERBS USED (via @sumosizedginger/my-game-engine-1.0/full):
 *   createBoxMesh, createCylinderMesh, extrudeProfile, transformMesh,
 *   mergeMeshIR, createMesh, createPart, createAnchor, triangleCount
 *
 * GAME-OWNED ADDITIONS, and why each one exists:
 *
 *   fuse() / assemble()
 *     A MeshIR part becomes one geometry group, and a geometry group is one
 *     draw call (src/render/mesh-adapter.js). Authoring a rope binding as its
 *     own part therefore costs a draw call. `fuse` concatenates many MeshIR
 *     inputs into ONE named part using the public `createMesh` / `createPart`
 *     constructors, so a rope can be built from forty primitives and still cost
 *     one draw call while keeping a meaningful semantic name.
 *     See ENGINE_GAPS.md — GAP-03.
 *
 *   revolve(), sphereoid(), roundedBox(), tube(), chain()
 *     Geometry Forge's accepted verbs are box, cylinder and convex extrusion.
 *     A boxing glove, a turnbuckle pad, a heavy bag and a human skull are lathe
 *     and bevel forms. Rather than approximating them with visible faceted
 *     boxes — the "procedural means crude" failure this build exists to
 *     disprove — these generators emit MeshIR through the SAME public
 *     constructors the engine verbs use. They are new shapes, not
 *     reimplementations of existing engine verbs.
 *     See ENGINE_GAPS.md — GAP-02.
 *
 *   quat helpers
 *     `transformMesh` requires a unit quaternion and refuses anything else.
 *     The engine's quaternion math (src/geometry/anchors.js multiplyQuaternions)
 *     is not part of the public surface, so the conversion lives here.
 *     See ENGINE_GAPS.md — GAP-04.
 */

import {
  createMesh,
  createPart,
  createBoxMesh,
  createCylinderMesh,
  extrudeProfile,
  transformMesh,
  mergeMeshIR,
  triangleCount,
  vertexCount
} from '@sumosizedginger/my-game-engine-1.0/full';

export { createBoxMesh, createCylinderMesh, extrudeProfile, transformMesh, mergeMeshIR, triangleCount, vertexCount };

// ---------------------------------------------------------------------------
// Deterministic randomness
// ---------------------------------------------------------------------------

/**
 * Seeded RNG.
 *
 * AGENTS.md forbids scattering `Math.random()` through deterministic systems
 * and requires an explicit named random service. The engine exposes no public
 * one (ENGINE_GAPS.md — GAP-05), so the game owns this. Every asset built with
 * it is reproducible from its seed.
 *
 * @param {number} seed
 * @returns {{next: Function, range: Function, pick: Function, int: Function, sign: Function}}
 */
export function createSeededRandom(seed) {
  let state = (seed >>> 0) || 0x9e3779b9;
  const next = () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
  return {
    next,
    range: (min, max) => min + next() * (max - min),
    int: (min, max) => Math.floor(min + next() * (max - min + 1)),
    pick: (list) => list[Math.floor(next() * list.length) % list.length],
    sign: () => (next() < 0.5 ? -1 : 1)
  };
}

// ---------------------------------------------------------------------------
// Rotation helpers — `transformMesh` refuses non-unit quaternions.
// ---------------------------------------------------------------------------

/**
 * Unit quaternion from intrinsic XYZ Euler angles (radians).
 *
 * @param {number} x
 * @param {number} y
 * @param {number} z
 * @returns {number[]} [x, y, z, w]
 */
export function quat(x = 0, y = 0, z = 0) {
  const cx = Math.cos(x / 2); const sx = Math.sin(x / 2);
  const cy = Math.cos(y / 2); const sy = Math.sin(y / 2);
  const cz = Math.cos(z / 2); const sz = Math.sin(z / 2);
  const q = [
    sx * cy * cz + cx * sy * sz,
    cx * sy * cz - sx * cy * sz,
    cx * cy * sz + sx * sy * cz,
    cx * cy * cz - sx * sy * sz
  ];
  // transformMesh enforces |q| == 1 within 1e-6; normalize explicitly so the
  // intent is ours rather than an accumulated floating-point accident.
  const len = Math.hypot(q[0], q[1], q[2], q[3]) || 1;
  return [q[0] / len, q[1] / len, q[2] / len, q[3] / len];
}

/**
 * Unit quaternion about an arbitrary axis.
 *
 * @param {number[]} axis
 * @param {number} angle - radians
 * @returns {number[]}
 */
export function quatAxis(axis, angle) {
  const len = Math.hypot(axis[0], axis[1], axis[2]) || 1;
  const s = Math.sin(angle / 2);
  const q = [(axis[0] / len) * s, (axis[1] / len) * s, (axis[2] / len) * s, Math.cos(angle / 2)];
  const n = Math.hypot(q[0], q[1], q[2], q[3]) || 1;
  return [q[0] / n, q[1] / n, q[2] / n, q[3] / n];
}

/**
 * Unit quaternion rotating +Y onto an arbitrary direction. Cylinders are
 * authored along +Y, so this is how a strut, rope or pipe gets aimed.
 *
 * @param {number[]} dir
 * @returns {number[]}
 */
export function quatFromUpTo(dir) {
  const len = Math.hypot(dir[0], dir[1], dir[2]) || 1;
  const d = [dir[0] / len, dir[1] / len, dir[2] / len];
  const dot = d[1];
  if (dot > 0.999999) return [0, 0, 0, 1];
  if (dot < -0.999999) return [1, 0, 0, 0];
  // axis = up x d
  const axis = [-d[2], 0, d[0]];
  return quatAxis(axis, Math.acos(Math.max(-1, Math.min(1, dot))));
}

/**
 * Places a MeshIR: engine `transformMesh` with Euler convenience.
 *
 * @param {object} mesh
 * @param {object} [options]
 * @returns {object} New MeshIR.
 */
export function place(mesh, { at = [0, 0, 0], rotate = null, rotation = null, scale = [1, 1, 1] } = {}) {
  return transformMesh(mesh, {
    translation: at,
    rotation: rotation ?? (rotate ? quat(rotate[0], rotate[1], rotate[2]) : [0, 0, 0, 1]),
    scale
  });
}

// ---------------------------------------------------------------------------
// Fusing — draw-call control without losing semantic identity
// ---------------------------------------------------------------------------

const EMPTY = Object.freeze([]);

function readAttr(mesh, name, itemSize, vertexTotal, fill) {
  const attr = mesh.attributes[name];
  if (attr) return attr;
  const out = new Float32Array(vertexTotal * itemSize);
  if (fill) out.fill(fill);
  return out;
}

/**
 * Concatenates many MeshIR inputs into ONE MeshIR carrying ONE named part.
 *
 * This is the game's answer to the part/draw-call coupling described at the top
 * of this file. It uses only `createMesh` and `createPart`, the same public
 * constructors the engine's own verbs use.
 *
 * @param {Array<object>} meshes
 * @param {object} options
 * @param {string} options.semanticName - Required; anonymous parts are refused.
 * @param {string} [options.id]
 * @param {string|null} [options.materialId]
 * @param {number} [options.regionId]
 * @param {number} [options.surfaceId]
 * @param {Array<object>} [options.anchors]
 * @returns {object} Single-part MeshIR.
 */
// Buffer concatenation for batching only. No welding, stitching, bridging or
// continuity guarantee. Deforming body seams require the public topology APIs.
export function fuse(meshes, { semanticName, id = null, materialId = null, regionId = 0, surfaceId = 0, anchors = EMPTY } = {}) {
  const list = meshes.filter(Boolean);
  if (list.length === 0) throw new Error(`fuse("${semanticName}") received no geometry`);

  let totalVerts = 0;
  let totalIndices = 0;
  for (const mesh of list) {
    totalVerts += mesh.attributes.position.length / 3;
    totalIndices += mesh.indices.length;
  }

  const position = new Float32Array(totalVerts * 3);
  const normal = new Float32Array(totalVerts * 3);
  const uv = new Float32Array(totalVerts * 2);
  const regionIds = new Uint16Array(totalVerts).fill(regionId);
  const surfaceIds = new Uint16Array(totalVerts).fill(surfaceId);
  const indices = new Uint32Array(totalIndices);

  let vOff = 0;
  let iOff = 0;
  for (const mesh of list) {
    const verts = mesh.attributes.position.length / 3;
    position.set(mesh.attributes.position, vOff * 3);
    normal.set(readAttr(mesh, 'normal', 3, verts, 0), vOff * 3);
    uv.set(readAttr(mesh, 'uv', 2, verts, 0), vOff * 2);
    for (let i = 0; i < mesh.indices.length; i++) indices[iOff + i] = mesh.indices[i] + vOff;
    vOff += verts;
    iOff += mesh.indices.length;
  }

  return createMesh({
    id: id ?? `fused:${semanticName}`,
    attributes: { position, normal, uv, regionId: regionIds, surfaceId: surfaceIds },
    indices,
    parts: [createPart({
      id: semanticName,
      semanticName,
      indexStart: 0,
      indexCount: indices.length,
      regionId,
      surfaceId,
      materialId
    })],
    anchors: [...anchors]
  });
}

/**
 * Builds a multi-part asset from named groups.
 *
 * Each group is fused into one part, so `parts.length` is the asset's draw-call
 * cost and every part still answers "what is this?" by name.
 *
 * @param {string} id - Asset id.
 * @param {Array<{name: string, material: string, meshes: Array<object>, region?: number, surface?: number}>} groups
 * @param {object} [options]
 * @param {Array<object>} [options.anchors]
 * @returns {object} MeshIR.
 */
export function assemble(id, groups, { anchors = EMPTY } = {}) {
  const parts = groups
    .filter((group) => group && group.meshes && group.meshes.filter(Boolean).length > 0)
    .map((group) => fuse(group.meshes, {
      semanticName: group.name,
      id: `${id}:${group.name}`,
      materialId: group.material,
      regionId: group.region ?? 0,
      surfaceId: group.surface ?? 0
    }));

  if (parts.length === 0) throw new Error(`assemble("${id}") produced no parts`);
  const merged = mergeMeshIR(parts, { id });
  return anchors.length > 0
    ? createMesh({
      id: merged.id,
      attributes: merged.attributes,
      indices: merged.indices,
      parts: merged.parts,
      anchors: [...merged.anchors, ...anchors],
      diagnostics: merged.diagnostics
    })
    : merged;
}

// ---------------------------------------------------------------------------
// Shapes the engine's verb set cannot express
// ---------------------------------------------------------------------------

/**
 * Lathes a 2D profile around the Y axis.
 *
 * `profile` is a list of [radius, y] rings, bottom to top. Radii of 0 close the
 * form into a point, which is how a glove nose or a bag cap is authored.
 * Normals are derived from the profile tangent, so the result shades as a
 * curved surface instead of a stack of visible bands.
 *
 * @param {object} options
 * @param {Array<number[]>} options.profile
 * @param {string} options.semanticName
 * @param {number} [options.segments=16]
 * @param {number} [options.arc=Math.PI * 2]
 * @returns {object} Single-part MeshIR.
 */
export function revolve({ profile, semanticName, id = null, segments = 16, arc = Math.PI * 2, materialId = null, regionId = 0, surfaceId = 0, squashZ = 1 }) {
  if (!Array.isArray(profile) || profile.length < 2) {
    throw new Error(`revolve("${semanticName}") requires at least 2 profile rings`);
  }
  const closed = Math.abs(arc - Math.PI * 2) < 1e-6;
  const cols = closed ? segments : segments + 1;
  const rows = profile.length;

  const positions = [];
  const normals = [];
  const uvs = [];
  const indices = [];

  // Per-ring surface tangent in the (r, y) plane gives a correct swept normal.
  const tangents = profile.map((_, r) => {
    const a = profile[Math.max(0, r - 1)];
    const b = profile[Math.min(rows - 1, r + 1)];
    const dr = b[0] - a[0];
    const dy = b[1] - a[1];
    const len = Math.hypot(dr, dy) || 1;
    return [dr / len, dy / len];
  });

  for (let r = 0; r < rows; r++) {
    const [radius, y] = profile[r];
    const [tr, ty] = tangents[r];
    for (let c = 0; c < cols; c++) {
      const theta = (c / segments) * arc;
      const cos = Math.cos(theta);
      const sin = Math.sin(theta);
      positions.push(radius * cos, y, radius * sin * squashZ);
      // Normal = rotate the profile normal (ty, -tr) around Y.
      const nr = ty;
      const ny = -tr;
      const nl = Math.hypot(nr, ny) || 1;
      const nx = (nr / nl) * cos;
      const nz = (nr / nl) * sin;
      const nyy = ny / nl;
      const nlen = Math.hypot(nx, nyy, nz) || 1;
      normals.push(nx / nlen, nyy / nlen, nz / nlen);
      uvs.push(c / segments, r / (rows - 1));
    }
  }

  for (let r = 0; r < rows - 1; r++) {
    for (let c = 0; c < (closed ? cols : cols - 1); c++) {
      const c1 = (c + 1) % cols;
      const a = r * cols + c;
      const b = r * cols + c1;
      const d = (r + 1) * cols + c;
      const e = (r + 1) * cols + c1;
      if (profile[r][0] > 1e-6 || profile[r + 1][0] > 1e-6) {
        indices.push(a, d, e);
        indices.push(a, e, b);
      }
    }
  }

  return singlePart({ id: id ?? `revolve:${semanticName}`, semanticName, positions, normals, uvs, indices, materialId, regionId, surfaceId });
}

/**
 * An ellipsoid. Heads, shoulder caps, bag bellies, sweat beads.
 *
 * @param {object} options
 * @returns {object} Single-part MeshIR.
 */
export function sphereoid({ radius = 0.5, scale = [1, 1, 1], semanticName, id = null, segments = 14, rings = 9, materialId = null, regionId = 0, surfaceId = 0, origin = [0, 0, 0] }) {
  const profile = [];
  for (let r = 0; r <= rings; r++) {
    const phi = (r / rings) * Math.PI;
    profile.push([Math.sin(phi) * radius, -Math.cos(phi) * radius]);
  }
  const base = revolve({ profile, semanticName, id, segments, materialId, regionId, surfaceId });
  return place(base, { at: origin, scale });
}

/**
 * A box with chamfered edges — padding, pads, crates, worn concrete curbs.
 *
 * Implemented as a 3x3x3 vertex cage so every silhouette edge catches light
 * instead of reading as a hard CAD corner. Geometry Forge has no bevel verb
 * (its own laws record topology-aware bevel as out of scope).
 *
 * @param {object} options
 * @returns {object} Single-part MeshIR.
 */
export function roundedBox({ size = [1, 1, 1], radius = 0.06, semanticName, id = null, materialId = null, regionId = 0, surfaceId = 0, origin = [0, 0, 0] }) {
  const [w, h, d] = size;
  const rx = Math.min(radius, w / 2 - 1e-4);
  const ry = Math.min(radius, h / 2 - 1e-4);
  const rz = Math.min(radius, d / 2 - 1e-4);

  const xs = [-w / 2, -w / 2 + rx, w / 2 - rx, w / 2];
  const ys = [-h / 2, -h / 2 + ry, h / 2 - ry, h / 2];
  const zs = [-d / 2, -d / 2 + rz, d / 2 - rz, d / 2];

  const positions = [];
  const normals = [];
  const uvs = [];
  const indices = [];
  const key = new Map();

  const vertex = (ix, iy, iz) => {
    const k = `${ix},${iy},${iz}`;
    const found = key.get(k);
    if (found !== undefined) return found;
    const x = xs[ix]; const y = ys[iy]; const z = zs[iz];
    // Normal points away from the inner cage, giving rounded corner shading.
    const nx = ix === 0 ? -1 : ix === 3 ? 1 : 0;
    const ny = iy === 0 ? -1 : iy === 3 ? 1 : 0;
    const nz = iz === 0 ? -1 : iz === 3 ? 1 : 0;
    const len = Math.hypot(nx, ny, nz) || 1;
    const index = positions.length / 3;
    positions.push(x + origin[0], y + origin[1], z + origin[2]);
    normals.push(nx / len, ny / len, nz / len);
    uvs.push((x / w) + 0.5, (y / h) + 0.5);
    key.set(k, index);
    return index;
  };

  const quadFace = (a, b, c, d2) => { indices.push(a, b, c, a, c, d2); };

  // Six faces of the cage, each subdivided 3x3 so the chamfer bands exist.
  const faces = [
    { fixed: 'z', at: 3, flip: false },
    { fixed: 'z', at: 0, flip: true },
    { fixed: 'x', at: 3, flip: true },
    { fixed: 'x', at: 0, flip: false },
    { fixed: 'y', at: 3, flip: true },
    { fixed: 'y', at: 0, flip: false }
  ];

  for (const face of faces) {
    for (let i = 0; i < 3; i++) {
      for (let j = 0; j < 3; j++) {
        let a; let b; let c; let d2;
        if (face.fixed === 'z') {
          a = vertex(i, j, face.at); b = vertex(i + 1, j, face.at);
          c = vertex(i + 1, j + 1, face.at); d2 = vertex(i, j + 1, face.at);
        } else if (face.fixed === 'x') {
          a = vertex(face.at, j, i); b = vertex(face.at, j, i + 1);
          c = vertex(face.at, j + 1, i + 1); d2 = vertex(face.at, j + 1, i);
        } else {
          a = vertex(i, face.at, j); b = vertex(i + 1, face.at, j);
          c = vertex(i + 1, face.at, j + 1); d2 = vertex(i, face.at, j + 1);
        }
        if (face.flip) quadFace(a, d2, c, b); else quadFace(a, b, c, d2);
      }
    }
  }

  return singlePart({ id: id ?? `rbox:${semanticName}`, semanticName, positions, normals, uvs, indices, materialId, regionId, surfaceId });
}

/**
 * A swept tube through a list of points — cables, chains' slack, conduit runs,
 * hanging wiring. Circular cross-section, mitre-free (each ring uses its own
 * local frame), which is fine for the gauges used here.
 *
 * @param {object} options
 * @returns {object} Single-part MeshIR.
 */
export function tube({ points, radius = 0.02, segments = 6, semanticName, id = null, materialId = null, regionId = 0, surfaceId = 0 }) {
  if (!Array.isArray(points) || points.length < 2) {
    throw new Error(`tube("${semanticName}") requires at least 2 points`);
  }
  const positions = [];
  const normals = [];
  const uvs = [];
  const indices = [];

  const frames = points.map((p, i) => {
    const prev = points[Math.max(0, i - 1)];
    const next = points[Math.min(points.length - 1, i + 1)];
    let t = [next[0] - prev[0], next[1] - prev[1], next[2] - prev[2]];
    const tl = Math.hypot(t[0], t[1], t[2]) || 1;
    t = [t[0] / tl, t[1] / tl, t[2] / tl];
    let up = Math.abs(t[1]) > 0.9 ? [1, 0, 0] : [0, 1, 0];
    let n = [
      t[1] * up[2] - t[2] * up[1],
      t[2] * up[0] - t[0] * up[2],
      t[0] * up[1] - t[1] * up[0]
    ];
    const nl = Math.hypot(n[0], n[1], n[2]) || 1;
    n = [n[0] / nl, n[1] / nl, n[2] / nl];
    const b = [
      t[1] * n[2] - t[2] * n[1],
      t[2] * n[0] - t[0] * n[2],
      t[0] * n[1] - t[1] * n[0]
    ];
    return { n, b };
  });

  for (let i = 0; i < points.length; i++) {
    const { n, b } = frames[i];
    for (let s = 0; s <= segments; s++) {
      const theta = (s / segments) * Math.PI * 2;
      const cos = Math.cos(theta);
      const sin = Math.sin(theta);
      const nx = n[0] * cos + b[0] * sin;
      const ny = n[1] * cos + b[1] * sin;
      const nz = n[2] * cos + b[2] * sin;
      positions.push(points[i][0] + nx * radius, points[i][1] + ny * radius, points[i][2] + nz * radius);
      normals.push(nx, ny, nz);
      uvs.push(s / segments, i / (points.length - 1));
    }
  }

  const cols = segments + 1;
  for (let i = 0; i < points.length - 1; i++) {
    for (let s = 0; s < segments; s++) {
      const a = i * cols + s;
      const bb = a + 1;
      const c = (i + 1) * cols + s;
      const d = c + 1;
      indices.push(a, c, d, a, d, bb);
    }
  }

  return singlePart({ id: id ?? `tube:${semanticName}`, semanticName, positions, normals, uvs, indices, materialId, regionId, surfaceId });
}

/**
 * Raw single-part MeshIR construction from arrays, through the public
 * constructors. Shared by every generator above.
 *
 * @param {object} options
 * @returns {object} MeshIR.
 */
export function singlePart({ id, semanticName, positions, normals, uvs, indices, materialId = null, regionId = 0, surfaceId = 0, anchors = EMPTY }) {
  const verts = positions.length / 3;
  return createMesh({
    id,
    attributes: {
      position: Float32Array.from(positions),
      normal: Float32Array.from(normals),
      uv: Float32Array.from(uvs),
      regionId: new Uint16Array(verts).fill(regionId),
      surfaceId: new Uint16Array(verts).fill(surfaceId)
    },
    indices: Uint32Array.from(indices),
    parts: [createPart({ id: semanticName, semanticName, indexStart: 0, indexCount: indices.length, regionId, surfaceId, materialId })],
    anchors: [...anchors]
  });
}

// ---------------------------------------------------------------------------
// Small compositional conveniences
// ---------------------------------------------------------------------------

/**
 * A box placed by its centre, in one call.
 *
 * @param {number[]} size
 * @param {number[]} at
 * @param {object} [options]
 * @returns {object} MeshIR.
 */
export function slab(size, at, { name = 'slab', rotate = null, material = null } = {}) {
  const mesh = createBoxMesh({ width: size[0], height: size[1], depth: size[2], semanticName: name, materialId: material });
  return place(mesh, { at, rotate });
}

/**
 * A cylinder whose ORIGIN IS ITS CENTRE (the engine verb uses the base), aimed
 * along an arbitrary axis. Struts, bolts, pipes and rope cords all want this.
 *
 * @param {object} options
 * @returns {object} MeshIR.
 */
export function rod({ radius = 0.05, radiusTop = null, length = 1, at = [0, 0, 0], dir = [0, 1, 0], segments = 8, name = 'rod', material = null }) {
  const mesh = createCylinderMesh({
    radiusTop: radiusTop ?? radius,
    radiusBottom: radius,
    height: length,
    radialSegments: segments,
    origin: { x: 0, y: -length / 2, z: 0 },
    semanticName: name,
    materialId: material
  });
  return place(mesh, { at, rotation: quatFromUpTo(dir) });
}

/**
 * A rod spanning two points.
 *
 * @param {number[]} a
 * @param {number[]} b
 * @param {object} [options]
 * @returns {object} MeshIR.
 */
export function strut(a, b, { radius = 0.04, segments = 8, name = 'strut', material = null } = {}) {
  const dir = [b[0] - a[0], b[1] - a[1], b[2] - a[2]];
  const length = Math.hypot(dir[0], dir[1], dir[2]);
  return rod({
    radius,
    length,
    at: [(a[0] + b[0]) / 2, (a[1] + b[1]) / 2, (a[2] + b[2]) / 2],
    dir,
    segments,
    name,
    material
  });
}

/**
 * A hanging chain: alternating links, each a flattened torus-ish ring built
 * from a revolve. Used for the heavy bag and the gantry drops.
 *
 * @param {object} options
 * @returns {Array<object>} MeshIR list (fuse them).
 */
export function chain({ from, to, links = 10, linkRadius = 0.035, thickness = 0.009, name = 'chain' }) {
  const out = [];
  const ringProfile = [];
  const steps = 6;
  for (let i = 0; i <= steps; i++) {
    const a = (i / steps) * Math.PI * 2;
    ringProfile.push([linkRadius + Math.cos(a) * thickness, Math.sin(a) * thickness]);
  }
  for (let i = 0; i < links; i++) {
    const t = (i + 0.5) / links;
    const p = [
      from[0] + (to[0] - from[0]) * t,
      from[1] + (to[1] - from[1]) * t,
      from[2] + (to[2] - from[2]) * t
    ];
    const ring = revolve({ profile: ringProfile, semanticName: `${name}-link-${i}`, segments: 6 });
    out.push(place(ring, { at: p, rotate: [Math.PI / 2, 0, i % 2 === 0 ? 0 : Math.PI / 2] }));
  }
  return out;
}

/**
 * Repeats a builder along a line, with deterministic jitter. The workhorse for
 * beams, columns, bleacher rows, crowd rows and rivets — repetition with
 * controlled variation is what separates authored density from noise.
 *
 * @param {number} count
 * @param {Function} builder - (index, t, rng) => MeshIR|MeshIR[]|null
 * @param {object} [rng]
 * @returns {Array<object>}
 */
export function repeat(count, builder, rng = null) {
  const out = [];
  for (let i = 0; i < count; i++) {
    const result = builder(i, count === 1 ? 0 : i / (count - 1), rng);
    if (Array.isArray(result)) out.push(...result.filter(Boolean));
    else if (result) out.push(result);
  }
  return out;
}
